import { useNavigate } from 'react-router-dom';

function LoginForm() {
  const navigate = useNavigate();

  const handleSubmit = () => {
    // Navigate to a new URL
    navigate('/dashboard');
    // Replace current entry
    navigate('/dashboard', { replace: true });
    // Go back
    navigate(-1);
  };

  return <button onClick={handleSubmit}>Login</button>;
}

